// ListBreakingTodos 执行生成的 ListBreakingTodos 数据库查询。
// 列出破坏性变更待办，按状态过滤并分页。
func (q *Queries) ListBreakingTodos(ctx context.Context, arg ListBreakingTodosParams) ([]BreakingTodo, error) {
	rows, err := q.db.Query(ctx, listBreakingTodos,
		arg.TenantID,
		arg.StatusFilter,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BreakingTodo{}
	for rows.Next() {
		var i BreakingTodo
		if err := rows.Scan(
			&i.TenantID,
			&i.ID,
			&i.AssetVersionID,
			&i.ServiceID,
			&i.Status,
			&i.AckedBy,
			&i.AckedAt,
			&i.Comment,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
